import {stopsFor,kindLabels,optionsFor} from './chapter.mjs';
import {campaignFor} from './campaign.mjs';
import {maxHp,maxEnergy} from './combat.mjs';
export function chapterProgress(s){const r=s.journey?.route;if(!r)return '';const remaining=Math.max(0,r.total-r.used);return `<section class="chapter-route"><div class="route-heading"><span>CHAPTER 0${campaignFor(s).id}</span><strong>${r.ended?'챕터 '+(r.ended==='victory'?'완료':'실패'):remaining?'보스까지 '+remaining+'회':'다음은 마지막 보스'}</strong></div><div class="route-track">${stopsFor(s).map((stop,i)=>{const entry=r.history.find(h=>h.step===i+1);const active=!r.ended&&((r.current?.step===i+1)||(!r.current&&r.used===i));return `<div class="route-stop ${i<r.used?'used':''} ${active?'current':''}" title="${i+1}번째 선택"><span>${i<r.used?'✓':i+1}</span><small>${entry?kindLabels[entry.kind]:'선택 '+(i+1)}</small></div>`;}).join('')}<div class="route-stop boss ${r.ended?'used':r.used>=r.total&&!r.current?'current':''}"><span>終</span><small>마지막 보스</small></div></div></section>`;}
export function routeCards(s){if(!['hub','map'].includes(s.scene))return '';const r=s.journey.route;
 if(r.ended)return `<div class="chapter-conclusion"><p class="eyebrow">${r.ended==='victory'?'CHAPTER COMPLETE':'CHAPTER ENDED'}</p><h3>${r.ended==='victory'?'여섯 선택이 만든 결말':'선택을 바꾸어 다시 도전할 수 있다'}</h3><p>다시 도전하면 이 챕터를 시작했던 능력과 소지품으로 돌아갑니다. 이번에 얻은 경험·장비·재화는 누적되지 않습니다.</p></div>`;
 if(r.used>=r.total)return `<div class="boss-gate"><img src="assets/combat/${campaignFor(s).bossArt}.png" alt="마지막 길을 지키는 ${campaignFor(s).bossName}"><div><p class="eyebrow">FINAL ENCOUNTER</p><h3>${campaignFor(s).bossName}</h3><p>보스</p><p>${r.intel.includes('read-pattern')?'정찰자의 정보로 강한 공격의 추가 위력이 1 줄었습니다.':''}</p></div></div>`;
 return `<div class="route-options">${optionsFor(s).map((o,i)=>{const disabled=o.kind==='rest'&&s.hp>=maxHp(s)&&s.energy>=maxEnergy(s);return `<button class="route-option unknown-route" data-choice="node-${o.id}" ${disabled?'disabled':''}><span class="route-kind-icon" aria-hidden="true">${{fight:'⚔',story:'◇',shop:'市',rest:'息',mentor:'書',forge:'鍛'}[o.kind]}</span><div class="route-option-copy"><small>선택 ${i+1}</small><h3>${kindLabels[o.kind]}</h3><strong>선택하기 →</strong></div></button>`;}).join('')}</div>`;
}
